-- NEXUS migration 0002: authoritative card catalog and transactional workflows.
-- Apply after 0001_nexus_schema.sql in Supabase SQL Editor.

create table public.card_catalog (
  id text primary key,
  season text not null,
  name text not null,
  rarity text not null,
  image_url text not null
);


create index card_catalog_name_idx on public.card_catalog using gin (to_tsvector('simple', name));

alter table public.deck_cards
  add constraint deck_cards_card_catalog_fk foreign key (card_id) references public.card_catalog(id);
alter table public.decks
  add constraint decks_principal_card_catalog_fk foreign key (principal_card_id) references public.card_catalog(id);

alter table public.card_catalog enable row level security;
create policy "card catalog is public read only" on public.card_catalog for select using (true);
revoke insert, update, delete on public.card_catalog from anon, authenticated;

-- A single transaction creates a pending submission and its ten ordered cards.
create or replace function public.submit_deck(
  p_name text,
  p_description text,
  p_strategy text,
  p_tier public.deck_tier,
  p_card_ids text[],
  p_principal_card_id text,
  p_combos text default '',
  p_strengths text default '',
  p_weaknesses text default ''
) returns uuid
language plpgsql security definer set search_path=public
as $$
declare
  v_user uuid := auth.uid();
  v_deck_id uuid;
  v_count integer;
begin
  if v_user is null then raise exception 'Devi accedere con Discord per inviare un mazzo'; end if;
  if not public.is_collaborator_or_owner() then raise exception 'Solo i collaboratori possono inviare mazzi'; end if;
  if length(trim(coalesce(p_name,''))) < 3 or length(p_name) > 80 then raise exception 'Nome mazzo non valido'; end if;
  if length(coalesce(p_description,'')) < 10 or length(p_description) > 500 then raise exception 'Descrizione non valida'; end if;
  if cardinality(p_card_ids) <> 10 then raise exception 'Un mazzo deve contenere esattamente 10 carte'; end if;
  select count(distinct x) into v_count from unnest(p_card_ids) x;
  if v_count <> 10 then raise exception 'Le 10 carte devono essere univoche'; end if;
  if not (p_principal_card_id = any(p_card_ids)) then raise exception 'La carta principale deve appartenere al mazzo'; end if;
  if exists(select 1 from unnest(p_card_ids) x left join public.card_catalog c on c.id=x where c.id is null) then
    raise exception 'Una o più carte non appartengono al catalogo NEXUS';
  end if;

  values(v_user,trim(p_name),trim(p_description),trim(coalesce(p_strategy,'')),p_tier,'pending',p_principal_card_id,coalesce(p_combos,''),coalesce(p_strengths,''),coalesce(p_weaknesses,''))
  returning id into v_deck_id;

  select v_deck_id, card_id, ordinality::smallint
  from unnest(p_card_ids) with ordinality as x(card_id,ordinality);

  values('deck_submitted','deck',v_deck_id::text,jsonb_build_object('name',trim(p_name),'author_id',v_user));
  values(v_user,'deck_submitted','deck',v_deck_id::text);
  return v_deck_id;
end;
$$;

-- Only the owner can approve/reject. Publishing timestamps are server-generated.
create or replace function public.review_deck(p_deck_id uuid, p_decision text)
returns void language plpgsql security definer set search_path=public
as $$
declare v_user uuid := auth.uid();
begin
  if v_user is null or not public.is_owner() then raise exception 'Operazione riservata al proprietario'; end if;
  if p_decision not in ('publish','reject') then raise exception 'Decisione non valida'; end if;
  if not exists(select 1 from public.decks where id=p_deck_id and status in ('pending','draft','rejected')) then
    raise exception 'Mazzo non trovato o non revisionabile';
  end if;
  if p_decision='publish' then
    if (select count(*) from public.deck_cards where deck_id=p_deck_id) <> 10 then raise exception 'Il mazzo deve contenere 10 carte'; end if;
    update public.decks set status='published', published_at=now(), approved_by=v_user, approved_at=now(), updated_at=now() where id=p_deck_id;
  else
    update public.decks set status='rejected', approved_by=v_user, approved_at=now(), updated_at=now() where id=p_deck_id;
  end if;
  values(v_user,'deck_'||p_decision,'deck',p_deck_id::text,jsonb_build_object('decision',p_decision));
end;
$$;

-- Replaces the public Tier List in one transaction and records its release time.
create or replace function public.publish_tierlist(p_entries jsonb, p_note text default '')
returns uuid language plpgsql security definer set search_path=public
as $$
declare v_user uuid := auth.uid(); v_release uuid;
begin
  if v_user is null or not public.is_owner() then raise exception 'Operazione riservata al proprietario'; end if;
  if jsonb_typeof(p_entries) <> 'array' then raise exception 'Formato Tier List non valido'; end if;
  if exists(
    select 1 from jsonb_to_recordset(p_entries) as x(deck_id uuid,tier text,sort_order integer)
    left join public.decks d on d.id=x.deck_id and d.status='published'
    where d.id is null or x.tier not in ('S','A','B','C')
  ) then raise exception 'La Tier List contiene mazzi non pubblicati o tier non validi'; end if;
  if (select count(*) from jsonb_to_recordset(p_entries) as x(deck_id uuid,tier text,sort_order integer)) <>
     (select count(distinct deck_id) from jsonb_to_recordset(p_entries) as x(deck_id uuid,tier text,sort_order integer))
  then raise exception 'Un mazzo non può comparire più di una volta'; end if;

  delete from public.tierlist_entries;
  select deck_id,tier::public.deck_tier,coalesce(sort_order,0)
  from jsonb_to_recordset(p_entries) as x(deck_id uuid,tier text,sort_order integer);
  values(v_user,'tierlist_published','tierlist',v_release::text);
  return v_release;
end;
$$;

revoke all on function public.submit_deck(text,text,text,public.deck_tier,text[],text,text,text,text) from public;
revoke all on function public.review_deck(uuid,text) from public;
revoke all on function public.publish_tierlist(jsonb,text) from public;
grant execute on function public.submit_deck(text,text,text,public.deck_tier,text[],text,text,text,text) to authenticated;
grant execute on function public.review_deck(uuid,text) to authenticated;
grant execute on function public.publish_tierlist(jsonb,text) to authenticated;

-- Public views used by the archive and Tier List; no draft data is exposed.
create or replace view public.published_deck_archive with (security_invoker=true) as
select d.id,d.name,d.description,d.strategy,d.tier,d.author_id,p.username,p.avatar_url,
       d.principal_card_id,c.name as principal_card_name,c.image_url as principal_card_image,
       d.published_at,(select count(*) from public.deck_likes l where l.deck_id=d.id) as likes_count
from public.decks d
join public.profiles p on p.id=d.author_id
join public.card_catalog c on c.id=d.principal_card_id
where d.status='published';

grant select on public.published_deck_archive to anon, authenticated;
